package httpapi

import (
	"A3S/internal/observatory"
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"sort"
	"strings"
	"sync"
	"time"
)

type requestIDKey struct{}

// RequestID is generated by this server, never trusted from an incoming header.
func RequestID(ctx context.Context) string { id, _ := ctx.Value(requestIDKey{}).(string); return id }

type observedWriter struct {
	http.ResponseWriter
	status int
	bytes  int64
	failed bool
}

func (w *observedWriter) Unwrap() http.ResponseWriter { return w.ResponseWriter }
func (w *observedWriter) WriteHeader(status int) {
	if status >= 100 && status < 200 {
		w.ResponseWriter.WriteHeader(status)
		return
	}
	if w.status == 0 {
		w.status = status
		w.ResponseWriter.WriteHeader(status)
	}
}
func (w *observedWriter) Write(p []byte) (int, error) {
	if w.status == 0 {
		w.WriteHeader(200)
	}
	n, err := w.ResponseWriter.Write(p)
	w.bytes += int64(n)
	if err != nil || n != len(p) {
		w.failed = true
	}
	return n, err
}

type countedBody struct {
	io.ReadCloser
	bytes int64
}

func (b *countedBody) Read(p []byte) (int, error) {
	n, e := b.ReadCloser.Read(p)
	b.bytes += int64(n)
	return n, e
}

// All labels come from fixed vocabularies, not names, URLs, headers or errors.
func operation(r *http.Request) string {
	if r.URL.Path == "/-/observatory/state" {
		return "observatory"
	}
	if r.URL.Path == "/-/usage" {
		return "usage"
	}
	if r.URL.Path == "/-/metrics" {
		return "metrics"
	}
	parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
	switch len(parts) {
	case 1:
		if r.URL.Path == "/" && r.Method == "GET" {
			return "list_buckets"
		}
		if parts[0] != "" {
			switch r.Method {
			case "GET", "HEAD":
				return "list_objects"
			case "PUT":
				return "create_bucket"
			case "DELETE":
				return "delete_bucket"
			}
		}
	case 2:
		switch r.Method {
		case "PUT":
			return "upload"
		case "DELETE":
			return "delete_object"
		case "HEAD":
			return "head"
		case "GET":
			if r.URL.Query().Get("metadata") == "1" {
				return "metadata"
			}
			return "download"
		}
	}
	return "other"
}

type metricKey struct {
	operation, outcome string
	status             int
}
type histogram struct {
	count   uint64
	sum     float64
	buckets [9]uint64
}

var durationBounds = [9]float64{.005, .01, .05, .1, .5, 1, 5, 30, 120}

type telemetry struct {
	observer                   *observatory.Monitor
	mu                         sync.Mutex
	requests                   map[metricKey]uint64
	durations                  map[string]histogram
	inflight                   int64
	uploadBytes, downloadBytes uint64
}

func newTelemetry() *telemetry {
	return &telemetry{requests: make(map[metricKey]uint64), durations: make(map[string]histogram)}
}
func (m *telemetry) wrap(next http.Handler, logger *slog.Logger) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if observatoryAsset(w, r) {
			return
		}
		start := time.Now()
		var random [16]byte
		_, _ = rand.Read(random[:])
		id := hex.EncodeToString(random[:])
		w.Header().Set("X-Request-ID", id)
		r = r.WithContext(context.WithValue(r.Context(), requestIDKey{}, id))
		rw := &observedWriter{ResponseWriter: w}
		body := &countedBody{ReadCloser: r.Body}
		if r.Body != nil {
			r.Body = body
		}
		op := operation(r)
		tracked := op != "metrics" && op != "observatory"
		if tracked && m.observer != nil {
			m.observer.Begin()
		}
		if tracked {
			m.mu.Lock()
			m.inflight++
			m.mu.Unlock()
		}
		defer func() {
			recovered := recover()
			outcome := "success"
			status := rw.status
			if status == 0 {
				status = 200
			}
			switch {
			case recovered == http.ErrAbortHandler:
				outcome = "aborted"
			case recovered != nil:
				outcome = "panic"
			case rw.failed:
				outcome = "write_error"
			case r.Context().Err() != nil:
				outcome = "canceled"
			case status >= 400:
				outcome = "error"
			}
			if recovered != nil && rw.status == 0 {
				status = 500
			}
			if status == 401 {
				op = "unauthorized"
			}
			elapsed := time.Since(start).Seconds()
			if tracked && m.observer != nil {
				m.observer.Finish(observatory.Event{RequestID: id, Operation: op, Status: status, Outcome: outcome, DurationMS: elapsed * 1000, RequestBytes: body.bytes, ResponseBytes: rw.bytes})
			}
			if tracked || status == 401 {
				m.mu.Lock()
				if tracked {
					m.inflight--
				}
				m.requests[metricKey{op, outcome, status}]++
				h := m.durations[op]
				h.count++
				h.sum += elapsed
				for i, b := range durationBounds {
					if elapsed <= b {
						h.buckets[i]++
					}
				}
				m.durations[op] = h
				if op == "upload" {
					m.uploadBytes += uint64(body.bytes)
				}
				if op == "download" && (status == 200 || status == 206) {
					m.downloadBytes += uint64(rw.bytes)
				}
				m.mu.Unlock()
				level := slog.LevelInfo
				if outcome != "success" {
					level = slog.LevelWarn
				}
				if status >= 500 || outcome == "panic" {
					level = slog.LevelError
				}
				logger.Log(r.Context(), level, "http_request", "request_id", id, "operation", op, "status", status, "outcome", outcome, "duration_seconds", elapsed, "request_bytes", body.bytes, "response_bytes", rw.bytes)
			}
			// Never let net/http log arbitrary panic values (which may contain secrets).
			if recovered != nil {
				panic(http.ErrAbortHandler)
			}
		}()
		next.ServeHTTP(rw, r)
	})
}

func (m *telemetry) serve(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" && r.Method != "HEAD" {
		w.Header().Set("Allow", "GET, HEAD")
		writeXMLError(w, "Method not allowed", 405)
		return
	}
	// Copy a bounded snapshot before writing to a potentially slow client.
	m.mu.Lock()
	requests := make(map[metricKey]uint64, len(m.requests))
	for k, v := range m.requests {
		requests[k] = v
	}
	durations := make(map[string]histogram, len(m.durations))
	for k, v := range m.durations {
		durations[k] = v
	}
	active, up, down := m.inflight, m.uploadBytes, m.downloadBytes
	m.mu.Unlock()
	var out strings.Builder
	out.WriteString("# HELP storage_http_requests_total Completed API requests by operation, status and outcome.\n# TYPE storage_http_requests_total counter\n")
	keys := make([]metricKey, 0, len(requests))
	for k := range requests {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		a, b := keys[i], keys[j]
		if a.operation != b.operation {
			return a.operation < b.operation
		}
		if a.status != b.status {
			return a.status < b.status
		}
		return a.outcome < b.outcome
	})
	for _, k := range keys {
		fmt.Fprintf(&out, "storage_http_requests_total{operation=%q,status=\"%d\",outcome=%q} %d\n", k.operation, k.status, k.outcome, requests[k])
	}
	out.WriteString("# HELP storage_operation_errors_total Failed API requests, including interrupted responses.\n# TYPE storage_operation_errors_total counter\n")
	for _, k := range keys {
		if k.outcome != "success" {
			fmt.Fprintf(&out, "storage_operation_errors_total{operation=%q,status=\"%d\",outcome=%q} %d\n", k.operation, k.status, k.outcome, requests[k])
		}
	}
	out.WriteString("# HELP storage_operation_duration_seconds API request duration including body transfer.\n# TYPE storage_operation_duration_seconds histogram\n")
	ops := make([]string, 0, len(durations))
	for op := range durations {
		ops = append(ops, op)
	}
	sort.Strings(ops)
	for _, op := range ops {
		h := durations[op]
		for i, b := range durationBounds {
			fmt.Fprintf(&out, "storage_operation_duration_seconds_bucket{operation=%q,le=\"%g\"} %d\n", op, b, h.buckets[i])
		}
		fmt.Fprintf(&out, "storage_operation_duration_seconds_bucket{operation=%q,le=\"+Inf\"} %d\nstorage_operation_duration_seconds_sum{operation=%q} %g\nstorage_operation_duration_seconds_count{operation=%q} %d\n", op, h.count, op, h.sum, op, h.count)
	}
	fmt.Fprintf(&out, "# HELP storage_http_inflight_requests Active API requests excluding metrics scrapes.\n# TYPE storage_http_inflight_requests gauge\nstorage_http_inflight_requests %d\n", active)
	fmt.Fprintf(&out, "# HELP storage_upload_bytes_total Upload body bytes consumed, including failed attempts.\n# TYPE storage_upload_bytes_total counter\nstorage_upload_bytes_total %d\n", up)
	fmt.Fprintf(&out, "# HELP storage_download_bytes_total Response body bytes written for 200 and 206 downloads, including partial transfers and multipart framing.\n# TYPE storage_download_bytes_total counter\nstorage_download_bytes_total %d\n", down)
	w.Header().Set("Content-Type", "text/plain; version=0.0.4; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Content-Length", fmt.Sprint(out.Len()))
	io.WriteString(w, out.String())
}
